INSERT INTO `#__guidedtours` (`title`, `uid`, `description`, `ordering`, `extensions`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `access`, `autostart`) VALUES ('Een artikel vergrendelen', 'joomlaguide-locking-an-article-nl', '<p>Als iemand een artikel bewerkt, <em>checkt</em> Joomla het <em>uit</em>: het is vergrendeld, zodat niemand anders het tegelijk kan wijzigen. Als het artikel wordt opgeslagen of gesloten, wordt het weer <em>ingecheckt</em>.</p><p>Gaat de bewerker weg zonder op te slaan of te sluiten, dan blijft het artikel vergrendeld. In deze rondleiding zie je hoe dat gebeurt en hoe een beheerder het ontgrendelt.</p><p>Deze rondleiding volgt de zelfstudie <a href="https://guide.joomla.org/nl/zelfstudies/inhoudsbeheer/7-publiceren-toegang/7-5-een-artikel-vergrendelen" target="_blank" rel="noopener">7.5 Een artikel vergrendelen</a> van de Joomla-gebruikershandleiding.</p>', 1, '["com_cpanel","com_content"]', 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', 'Joomla User Guide: 7.5 Locking an Article', 1, 1);
INSERT INTO `#__guidedtour_steps` (`tour_id`, `title`, `description`, `ordering`, `position`, `target`, `type`, `interactive_type`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `params`) VALUES
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-nl'), 'Inhoud', '<p>Klik in het menu links op <strong>Inhoud</strong>.</p><p>Het gaat open en laat zien wat je daar kunt doen.</p>', 1, 'right', 'body.com_cpanel #sidebarmenu li.item-level-1:has(a[href="index.php?option=com_content&view=articles"]) > a.has-arrow', 2, 4, 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-nl'), 'Inhoud › Artikelen', '<p>Klik onder <strong>Inhoud</strong> op <strong>Artikelen</strong>.</p>', 2, 'right', 'body.com_cpanel #sidebarmenu a[href="index.php?option=com_content&view=articles"]', 2, 1, 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-nl'), 'Het artikel openen', '<p>Klik op <strong>Gemeenteraad keurt nieuw vervoersbudget goed</strong> om het te bewerken.</p>', 3, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Gemeenteraad keurt nieuw vervoersbudget goed"]) a[href*="task=article.edit"]', 2, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-nl'), 'Weggaan zonder te sluiten', '<p>Je bewerkt het artikel nu. Klik niet op <strong>Opslaan</strong> of <strong>Sluiten</strong>: druk op de knop <em>Terug</em> van je browser. Dat doet een bewerker die weggaat zonder te sluiten.</p><p>Terug in de lijst heeft het artikel een slotje: het is uitgecheckt. Beweeg de muis over het slotje om te zien wie het heeft uitgecheckt, en wanneer. (Geen slotje? Laad de pagina opnieuw.)</p>', 4, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Gemeenteraad keurt nieuw vervoersbudget goed"]) th', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-nl'), 'Wie kan het bewerken?', '<p>Jij hebt het artikel uitgecheckt, dus jij kunt het nog openen. Andere gebruikers, zelfs beheerders, krijgen een foutmelding als ze het proberen.</p><p>Als je in het artikel op <strong>Sluiten</strong> of <strong>Opslaan & sluiten</strong> klikt, wordt het weer ingecheckt.</p>', 5, 'bottom', '#articleList tr:has(a[href*="task=article.edit"][title$=" Gemeenteraad keurt nieuw vervoersbudget goed"])', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-nl'), 'Het artikel inchecken', '<p>Hier kwam de bewerker niet terug. Als beheerder kun je het artikel ontgrendelen: klik op het slotje.</p>', 6, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Gemeenteraad keurt nieuw vervoersbudget goed"]) [data-item-task="articles.checkin"]', 2, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-nl'), 'Goed gedaan!', '<p>Het artikel is ingecheckt, en iedereen met de juiste rechten kan het weer bewerken.</p><p>Om veel artikelen tegelijk in te checken, vink je hun selectievakjes aan en kies je <strong>Acties</strong> › <strong>Inchecken</strong>.</p><p>Let op: als de bewerker nog aan het artikel werkt, kunnen zijn wijzigingen verloren gaan.</p>', 7, 'bottom', '#system-message-container', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL);
